input.content:
#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL files from the migrations directory and logs them in order
 */
function main() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort((a, b) => {
      // Sort by filename (this will handle numeric prefixes like 001, 002, etc.)
      return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
    });

  // Check if there are any SQL files
  if (sqlFiles.length === 0) {
    console.log(`No SQL migration files found in '${MIGRATIONS_DIR}'.`);
    return;
  }

  // Log each filename
  console.log(`Found ${sqlFiles.length} migration(s) to apply:`);
  console.log('');

  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
}

// Run the script
if (require.main === module) {
  main();
}

