const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = './.env.test';

/**
 * Reads environment variables from a .env file
 * @param {string} envFilePath - Path to the .env file
 * @returns {Object} Object containing key-value pairs from the .env file
 */
function readEnvFile(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    throw new Error(`Environment file '${envFilePath}' does not exist.`);
  }

  const envContent = fs.readFileSync(envFilePath, 'utf-8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    const trimmedLine = line.trim();

    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }

    // Parse KEY=VALUE pairs
    const equalsIndex = trimmedLine.indexOf('=');
    if (equalsIndex > 0) {
      const key = trimmedLine.substring(0, equalsIndex).trim();
      let value = trimmedLine.substring(equalsIndex + 1).trim();

      // Remove quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) || 
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.substring(1, value.length - 1);
      }

      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Simulates a database connection (just logs success)
 * @param {string} databaseUrl - The database connection URL
 */
function simulateDatabaseConnection(databaseUrl) {
  // Mask the password in the URL for security when logging
  const maskedUrl = databaseUrl.replace(/:(\w+)@/, ':****@');
  console.log(`Connected to database: ${maskedUrl}`);
}

// Run the script
if (require.main === module) {
  // Read and parse the environment file
  let envVars;
  try {
    envVars = readEnvFile(ENV_FILE);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }

  // Check for DATABASE_URL
  const databaseUrl = envVars.DATABASE_URL;
  if (!databaseUrl) {
    console.error(`Error: DATABASE_URL not found in '${ENV_FILE}'.`);
    process.exit(1);
  }

  // Simulate database connection (just log success)
  simulateDatabaseConnection(databaseUrl);
  console.log('');

  // List migrations
  listMigrations();
}

