#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL files from the migrations directory and logs them in order
 */
function main() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort((a, b) => {
      // Sort by filename (this will handle numeric prefixes like 001, 002, etc.)
      return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
    });

  // Check if there are any SQL files
  if (sqlFiles.length === 0) {
    console.log(`No SQL migration files found in '${MIGRATIONS_DIR}'.`);
    return;
  }

  // Log each filename
  console.log(`Found ${sqlFiles.length} migration(s) to apply:`);
  console.log('');

  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
}

// Run the script
if (require.main === module) {
  main();
}

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

function logMigrations(files) {
  if (files.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s):`);
  console.log('=====================================');

  files.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('=====================================');
  console.log('These migrations would be applied in the order shown above.');
}

function main() {
  console.log('Database Migration Script');
  console.log('==========================\n');

  const migrationFiles = getMigrationFiles();
  logMigrations(migrationFiles);
}

// Run the script
main();

