  try {
    // Extract database name from postgres://user:pass@host:port/dbname
    const match = databaseUrl.match(/\/\/[^\/]+\/(.+)$/);
    return match ? match[1] : 'unknown';
  } catch (error) {
    return 'unknown';
  }
}

