const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = './.env.test';

// Load environment variables from .env file
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`.env file not found at ${filePath}`);
  }

  const envContent = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    // Skip comments and empty lines
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const [key, ...valueParts] = trimmedLine.split('=');
      if (key && valueParts.length > 0) {
        const value = valueParts.join('=').trim();
        envVars[key.trim()] = value;
      }
    }
  });

  return envVars;
}

async function runMigrations() {
  try {
    // Load environment variables
    console.log('Loading environment variables...');
    const envVars = loadEnvFile(ENV_FILE);
    const databaseUrl = envVars.DATABASE_URL;

    if (!databaseUrl) {
      throw new Error('DATABASE_URL not found in .env.test file');
    }

    console.log('✓ Environment variables loaded');
    console.log(`✓ Database connection string resolved: ${databaseUrl}`);
    console.log('✓ Successfully connected to database (mock connection)');
    console.log('');

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sort alphabetically for consistent order

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in migrations directory.');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration file(s):`);
    console.log('=====================================');

    // Log each file name
    sqlFiles.forEach((file, index) => {
      const fullPath = path.join(MIGRATIONS_DIR, file);
      console.log(`${index + 1}. ${file}`);
    });

    console.log('=====================================');
    console.log('Migration order determined.');

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrations();

